#!/usr/bin/env Rscript

.medium_o2_report_dir <- local({
  frames <- Filter(nzchar, vapply(sys.frames(), function(env) {
    if (is.null(env$ofile)) "" else normalizePath(env$ofile, mustWork = FALSE)
  }, character(1L)))
  own <- frames[basename(frames) == "render_medium_o2_window_report.R"]
  if (length(own)) return(dirname(own[[length(own)]]))
  file_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  if (length(file_arg)) {
    return(dirname(normalizePath(sub("^--file=", "", file_arg[[1L]]), mustWork = FALSE)))
  }
  normalizePath(getwd(), mustWork = FALSE)
})
.medium_o2_report_root <- normalizePath(file.path(.medium_o2_report_dir, "..", ".."), mustWork = FALSE)
source(
  file.path(.medium_o2_report_root, "util", "o2_supply_demand_map_report_utils.R"),
  local = environment()
)
rm(.medium_o2_report_dir, .medium_o2_report_root)

parse_args <- o2sd_report_parse_equals_args
`%||%` <- o2sd_report_null_coalesce_simple
safe_read <- o2sd_report_safe_read_delim

run_medium_o2_window_report <- function(argv = parse_args()) {
  simulation_dir <- argv$simulation_dir
  analysis_dir <- argv$analysis_dir
  viz_dir <- argv$viz_dir
  report_dir <- argv$report_dir %||% argv$out_dir
  required <- c(
    file.path(simulation_dir, "simulation_manifest.tsv"),
    file.path(analysis_dir, "analysis_manifest.tsv"),
    file.path(viz_dir, "visualization_manifest.tsv")
  )
  missing <- required[!file.exists(required)]
  if (length(missing)) stop("Medium-O2 report requires completed upstream manifests: ", paste(missing, collapse = ", "))
  if (is.null(report_dir) || !nzchar(report_dir)) stop("Missing --report_dir (or --out_dir).")
  features <- safe_read(file.path(analysis_dir, "tables", "medium_o2_features_by_seed.tsv"))
  windows <- safe_read(file.path(analysis_dir, "tables", "medium_o2_windows.tsv"))
  duration <- safe_read(file.path(analysis_dir, "tables", "medium_o2_duration_summary_by_regime.tsv"))
  tests <- safe_read(file.path(analysis_dir, "tables", "medium_o2_feature_regime_tests.tsv"))
  correlations <- safe_read(file.path(analysis_dir, "tables", "medium_o2_parameter_correlations.tsv"))
  figures <- safe_read(file.path(viz_dir, "visualization_manifest.tsv"))
  counts <- if ("trajectory_regime" %in% names(features)) table(features$trajectory_regime, useNA = "ifany") else integer()
  top_tests <- if (nrow(tests) && "BH_adjusted_p_value" %in% names(tests)) utils::head(tests[order(tests$BH_adjusted_p_value), , drop = FALSE], 20L) else tests
  top_corr <- if (nrow(correlations) && "abs_spearman_rho" %in% names(correlations)) utils::head(correlations[order(-correlations$abs_spearman_rho), , drop = FALSE], 30L) else correlations
  lines <- c(
    "# In vivo medium-O2 window analysis", "",
    paste0("- analyzed seeds: ", nrow(features)),
    paste0("- O2 windows: ", paste(paste0(windows$low, "-", windows$high, "%"), collapse = ", ")),
    paste0("- figures: ", nrow(figures)), "", "## Regime counts", "",
    if (length(counts)) paste0("- ", names(counts), ": ", as.integer(counts)) else "No regime labels were supplied in the simulation contract.",
    "", "## Medium-O2 duration summary", "",
    utils::capture.output(print(duration, row.names = FALSE)),
    "", "## Mode comparison", "",
    utils::capture.output(print(top_tests, row.names = FALSE)),
    "", "## Parameter correlations", "",
    utils::capture.output(print(top_corr, row.names = FALSE)),
    "", "## Notes", "",
    "Durations and AUCs use linear interpolation over pre-existing O2 timecourses; no trajectory is generated by analysis or reporting."
  )
  dir.create(report_dir, recursive = TRUE, showWarnings = FALSE)
  path <- file.path(report_dir, "analysis_summary.md")
  writeLines(lines, path)
  manifest <- data.frame(artifact = "analysis_summary", relative_path = "analysis_summary.md", role = "report", path = normalizePath(path, mustWork = TRUE), exists = TRUE)
  utils::write.table(manifest, file.path(report_dir, "report_manifest.tsv"), sep = "\t", quote = FALSE, row.names = FALSE)
  invisible(report_dir)
}

if (sys.nframe() == 0L) run_medium_o2_window_report()
